const controls = {
  cover: { type: 'image', label: 'Cover' },
};

function draw(ctx, t, c, clip) {
  const img = M.image('cover');
  if (!img) return;
  ctx.drawImage(img, 0, 0, clip.width, clip.height);
}

const controls = {
  name: { type: 'text', label: 'Name', default: 'KorgiTranslate' },
  line: { type: 'text', label: 'Line', default: '选中，即译' },
  icon: { type: 'image', label: 'Icon' },
  accent: { type: 'color', label: 'Accent', default: '#50CDCF' },
  ink: { type: 'color', label: 'Ink', default: '#F4F4F6' },
};

function round(ctx, x, y, w, h, r) {
  ctx.beginPath();
  ctx.roundRect(x, y, w, h, r);
}

function draw(ctx, t, c, clip) {
  const W = clip.width;
  const H = clip.height;
  const k = M.ease.outCubic(M.clamp(t / 0.28));
  const iconSize = 188;
  const nameSize = 90;
  const lineSize = 52;
  ctx.save();
  ctx.font = M.font(nameSize, 'system-ui', 650);
  const nameW = ctx.measureText(c.name).width;
  ctx.font = M.font(lineSize, 'PingFang SC', 500);
  const lineW = ctx.measureText(c.line).width;
  const gap = 40;
  const textW = Math.max(nameW, lineW);
  const blockW = iconSize + gap + textW;
  const x0 = (W - blockW) / 2;
  const y0 = (H - iconSize) / 2 + (1 - k) * 28;
  ctx.globalAlpha = k;
  if (c.icon && c.icon.width) {
    ctx.save();
    round(ctx, x0, y0, iconSize, iconSize, 36);
    ctx.clip();
    ctx.drawImage(c.icon, x0, y0, iconSize, iconSize);
    ctx.restore();
  }
  const tx = x0 + iconSize + gap;
  ctx.textAlign = 'left';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = c.ink;
  ctx.font = M.font(nameSize, 'system-ui', 650);
  ctx.fillText(c.name, tx, y0 + iconSize * 0.34);
  ctx.fillStyle = c.accent;
  ctx.font = M.font(lineSize, 'PingFang SC', 500);
  ctx.fillText(c.line, tx, y0 + iconSize * 0.7);
  ctx.restore();
}
